#include <iostream>
#include <vector>
class Stock {
  int quantity_ = 2;
public:
  bool change(int delta) {
    if (delta < -20 || delta > 20 || quantity_ + delta < 0 || quantity_ + delta > 20) return false;
    quantity_ += delta; return true;
  }
  int quantity() const { return quantity_; }
};
struct View { int last = -1; void show(int value) { last = value; } };
class Presenter {
  Stock& model_; View& view_;
public:
  Presenter(Stock& m, View& v) : model_(m), view_(v) { view_.show(model_.quantity()); }
  bool onChange(int delta) { bool ok = model_.change(delta); view_.show(model_.quantity()); return ok; }
};
int main() {
  int n;
  if (!(std::cin >> n) || n < 0 || n > 12) { std::cout << "invalid\n"; return 0; }
  std::vector<int> commands(n);
  for (int& x : commands) if (!(std::cin >> x)) { std::cout << "invalid\n"; return 0; }
  std::cin >> std::ws;
  if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
  Stock model; View view; Presenter presenter(model, view); int rejected = 0;
  for (int x : commands) if (!presenter.onChange(x)) ++rejected;
  std::cout << "stock " << view.last << " rejected " << rejected << '\n';
}
